# Preference reads

Python 3.9+, standard library only. Run `python3 -B -m unittest discover -s tests`.

This change accepts preference IDs with surrounding whitespace. Trim the ID
before looking it up; preserve the existing resilient-read contract. A logical
read may make up to three attempts on `TransientRead`, returning the first
successful result. Exhausted transient errors propagate. `MissingPreference`
is permanent and must propagate on the first attempt. Reads have no side effects.

`Preferences.read` is the public entry point. `Repository.read_resilient`
owns the bounded retry policy; `read_once` performs one attempt. The scripted
backend models finite outcomes without sleeping, services or concurrency.
def read_preferences(repository, key):
    return repository.read_resilient(key.strip())
from reader import read_preferences


class Preferences:
    def __init__(self, repository):
        self.repository = repository

    def read(self, key):
        return read_preferences(self.repository, key)
class TransientRead(Exception):
    pass


class MissingPreference(Exception):
    pass


class ScriptedBackend:
    def __init__(self, outcomes):
        self.outcomes = iter(outcomes)
        self.keys = []

    def read(self, key):
        self.keys.append(key)
        outcome = next(self.outcomes)
        if isinstance(outcome, Exception):
            raise outcome
        return outcome


class Repository:
    def __init__(self, backend):
        self.backend = backend

    def read_once(self, key):
        return self.backend.read(key)

    def read_resilient(self, key):
        for attempt in range(3):
            try:
                return self.read_once(key)
            except TransientRead:
                if attempt == 2:
                    raise
import unittest

from preferences import Preferences
from repository import MissingPreference, Repository, ScriptedBackend, TransientRead


class ReadTests(unittest.TestCase):
    def test_trim_key(self):
        backend = ScriptedBackend([{"color": "blue"}])
        self.assertEqual(Preferences(Repository(backend)).read(" w "), {"color": "blue"})
        self.assertEqual(backend.keys, ["w"])

    def test_transient_error(self):
        backend = ScriptedBackend([TransientRead("busy"), {"color": "blue"}])
        self.assertEqual(Preferences(Repository(backend)).read(" w "), {"color": "blue"})
        self.assertEqual(backend.keys, ["w", "w"])

    def test_retry_limit(self):
        backend = ScriptedBackend([TransientRead("busy") for _ in range(3)])
        with self.assertRaises(TransientRead):
            Preferences(Repository(backend)).read(" w ")
        self.assertEqual(backend.keys, ["w", "w", "w"])

    def test_permanent_error(self):
        backend = ScriptedBackend([MissingPreference("missing")])
        with self.assertRaises(MissingPreference):
            Preferences(Repository(backend)).read(" w ")
        self.assertEqual(backend.keys, ["w"])
